// Some portions generated by Claude
// The arrow router's shortcuts (a detour search that skips legs which cannot win, obstacle lookups along a segment
// instead of under its box, distances not measured for cards a leg's line stays clear of) change no route: every bend
// and every point equals the frozen router's, on ordinary drawings and on awkward ones.
import assert from 'node:assert/strict';
import test from 'node:test';
import { routeEdges } from '../../../main/frontend/graph-explorer/graph-edge-router.ts';
import { lineMissesBox, segmentHitsBox } from '../../../main/frontend/graph-explorer/graph-layout-stress.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { createStarStressGraph } from '../../../main/frontend/graph-explorer/graph-fixtures.ts';
import { routeEdges as referenceRouteEdges } from './support/reference-router.ts';
import { sharedHubNetwork } from './fixtures/layout-networks.mjs';
import { gridNetwork, karateNetwork } from './fixtures/layout-diverse.mjs';

function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

/** Cards scattered over an area, every one linked a few times: `spread` pixels per card decides how crowded it is. */
function scattered(count, links, spread, seed) {
  const next = random(seed), side = Math.sqrt(count) * spread;
  const nodes = Array.from({ length: count }, (_, i) => ({
    id: `n${i}`, label: i % 4 ? `Resource ${i}` : `A resource with a rather longer label ${i}`, kind: i % 9 ? 'iri' : 'literal',
    x: next() * side * 1.6, y: next() * side,
  }));
  const edges = [];
  for (let i = 0; i < links; i++) {
    const a = Math.floor(next() * count), b = Math.floor(next() * count);
    edges.push({ id: `e${i}`, source: `n${a}`, target: `n${b}`, label: 'linked', predicate: `urn:p${i % 3}` });
  }
  return { nodes, edges };
}

function sameRouting(nodes, edges, name) {
  let expected;
  try {
    expected = referenceRouteEdges(nodes, edges);
  } catch (error) {
    // A drawing the frozen router refuses is refused in the same way.
    assert.throws(() => routeEdges(nodes, edges), { name: error.name, message: error.message }, `${name}: refusal`);
    return null;
  }
  const actual = routeEdges(nodes, edges);
  assert.deepEqual([...actual.bends], [...expected.bends], `${name}: bends`);
  assert.deepEqual([...actual.routes.keys()], [...expected.routes.keys()], `${name}: routed arrows`);
  for (const [id, route] of expected.routes) assert.deepEqual(actual.routes.get(id), route, `${name}: route of ${id}`);
  return expected;
}

async function placed(graph) {
  const { positions } = await computeGraphLayout(graph, { aspectRatio: 1.6, includeRoutes: false });
  return graph.nodes.map((node) => ({ ...node, ...positions.get(node.id) }));
}

test('laid-out drawings get the frozen router\'s routes', async () => {
  let routed = 0, detours = 0;
  for (const [name, graph] of [['shared hubs', sharedHubNetwork()], ['star', createStarStressGraph(90, 1)],
    ['grid', gridNetwork(9)], ['karate', karateNetwork()]]) {
    const expected = sameRouting(await placed(graph), graph.edges, name);
    routed += expected.routes.size;
    for (const route of expected.routes.values()) if (route.points.length > 2) detours++;
  }
  assert.ok(routed > 20 && detours > 0, `the drawings exercise moved ports and detours (${routed} routes, ${detours} detours)`);
});

test('crowded, overlapping and sparse scatters get the frozen router\'s routes', () => {
  let detours = 0, declined = 0;
  for (const [count, links, spread, seed] of [[60, 140, 150, 1], [120, 260, 110, 2], [200, 420, 190, 3], [90, 200, 40, 4],
    [40, 60, 600, 5], [260, 300, 140, 6]]) {
    const { nodes, edges } = scattered(count, links, spread, seed);
    const expected = sameRouting(nodes, edges, `scatter ${count}/${links}/${spread}`);
    for (const route of expected.routes.values()) if (route.points.length > 2) detours++;
    declined += edges.length - expected.routes.size;
  }
  assert.ok(detours > 50, `the scatters exercise the detour search (${detours} detours)`);
  assert.ok(declined > 50, `and arrows that stay straight (${declined})`);
});

test('awkward drawings get the frozen router\'s routes', () => {
  const base = scattered(70, 170, 130, 11);
  const variants = {
    'far from the origin': base.nodes.map((node) => ({ ...node, x: node.x + 4e7, y: node.y - 9e6 })),
    'one card without a place': base.nodes.map((node, i) => (i === 7 ? { ...node, x: NaN, y: NaN } : node)),
    'cards never placed': base.nodes.map((node, i) => (i % 10 === 3 ? { id: node.id, label: node.label, kind: node.kind } : node)),
    'cards in one row': base.nodes.map((node, i) => ({ ...node, x: i * 240, y: 0 })),
    'cards on one spot': base.nodes.map((node, i) => (i % 5 ? node : { ...node, x: 300, y: 200 })),
    'fractional places': base.nodes.map((node) => ({ ...node, x: node.x / 3, y: node.y * Math.SQRT2 })),
  };
  for (const [name, nodes] of Object.entries(variants)) sameRouting(nodes, base.edges, name);
  // Loops, parallel arrows and arrows to cards that are not there.
  const edges = [...base.edges, { id: 'loop', source: 'n1', target: 'n1', label: 'self', predicate: 'urn:self' },
    { id: 'twin-a', source: 'n2', target: 'n3', label: 'a', predicate: 'urn:a' }, { id: 'twin-b', source: 'n3', target: 'n2', label: 'b', predicate: 'urn:b' },
    { id: 'gone', source: 'n4', target: 'missing', label: 'gone', predicate: 'urn:gone' }];
  sameRouting(base.nodes, edges, 'loops, parallel and dangling arrows');
  sameRouting([], [], 'nothing');
});

test('a line that misses a box by the half pixel rules out every segment on it', () => {
  const next = random(20261128);
  const scales = [1, 1, 1, 40, 2500, 1e7];
  let missed = 0, hit = 0;
  for (let round = 0; round < 60000; round++) {
    const scale = scales[round % scales.length], at = () => (next() - 0.5) * 2000 * scale;
    const x0 = at(), y0 = at();
    // Slanted, axis-parallel and very short directions.
    const kind = round % 5, ex = kind === 1 ? 0 : (next() - 0.5) * (kind === 4 ? 1e-3 : 900 * scale), ey = kind === 2 ? 0 : (next() - 0.5) * (kind === 4 ? 1e-3 : 900 * scale);
    const minX = at(), minY = at(), maxX = minX + next() * 260 * (round % 7 ? 1 : scale), maxY = minY + next() * 80 * (round % 7 ? 1 : scale);
    if (!lineMissesBox(x0, y0, ex, ey, minX, minY, maxX, maxY)) { hit++; continue; }
    missed++;
    // The segment itself, and longer and shorter segments on the same line in both directions.
    for (const [from, to] of [[0, 1], [-3, 4], [0.25, 0.5], [-40, -2], [1, 60]]) {
      assert.equal(segmentHitsBox(x0 + ex * from, y0 + ey * from, x0 + ex * to, y0 + ey * to, minX, minY, maxX, maxY), false,
        JSON.stringify({ x0, y0, ex, ey, minX, minY, maxX, maxY, from, to }));
    }
  }
  assert.ok(missed > 20000 && hit > 1000, `both answers occur (${missed} misses, ${hit} others)`);
  // No direction, or no coordinates: never a miss, so the exact test decides.
  assert.equal(lineMissesBox(0, 0, 0, 0, 10, 10, 20, 20), false);
  assert.equal(lineMissesBox(NaN, 0, 1, 1, 10, 10, 20, 20), false);
  assert.equal(lineMissesBox(0, 0, 1, NaN, 10, 10, 20, 20), false);
  assert.equal(lineMissesBox(0, 0, 1, 0, 10, 10, NaN, 20), false);
  // A line that only just touches the box, or passes within the half pixel, is left to the exact test as well.
  assert.equal(lineMissesBox(0, 9.75, 1, 0, 10, 10, 20, 20), false);
  assert.equal(lineMissesBox(0, 9, 1, 0, 10, 10, 20, 20), true);
});
